+	if ((flags & MAP_TYPE) != MAP_SHARED)
+		return -EOPNOTSUPP;
+
+	if (flags & ~(MAP_TYPE | VM_MMAP_REMOTE_FLAGS))
+		return -EOPNOTSUPP;
